const lockSquadForAutopilotAssignment = `-- name: LockSquadForAutopilotAssignment :one
SELECT id, workspace_id, name, description, leader_id, creator_id, created_at, updated_at, archived_at, archived_by, avatar_url, instructions, inherit_runtime_skills, runtime_skill_exceptions FROM squad
WHERE id = $1 AND workspace_id = $2
FOR SHARE
`

type LockSquadForAutopilotAssignmentParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

// Stabilizes the squad-to-leader resolution while an active Autopilot is
// created, retargeted, or resumed. FOR SHARE conflicts with an ordinary
// leader_id update, so the caller subsequently locks the same leader Agent
// whose row Runtime teardown serializes against.
func (q *Queries) LockSquadForAutopilotAssignment(ctx context.Context, arg LockSquadForAutopilotAssignmentParams) (Squad, error) {
	row := q.db.QueryRow(ctx, lockSquadForAutopilotAssignment, arg.ID, arg.WorkspaceID)
	var i Squad
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.LeaderID,
		&i.CreatorID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ArchivedAt,
		&i.ArchivedBy,
		&i.AvatarUrl,
		&i.Instructions,
		&i.InheritRuntimeSkills,
		&i.RuntimeSkillExceptions,
	)
	return i, err
}

const lockSquadForUpdate = `-- name: LockSquadForUpdate :one
SELECT id, workspace_id, name, description, leader_id, creator_id, created_at, updated_at, archived_at, archived_by, avatar_url, instructions, inherit_runtime_skills, runtime_skill_exceptions FROM squad
WHERE id = $1 AND workspace_id = $2
FOR UPDATE
`

type LockSquadForUpdateParams struct {
	ID          pgtype.UUID `json:"id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

// Squad leader changes take the exclusive side of the same lock used by
// Autopilot assignment. The handler then locks the proposed leader Agent and
// pauses active squad Autopilots when that Agent is unbound.
func (q *Queries) LockSquadForUpdate(ctx context.Context, arg LockSquadForUpdateParams) (Squad, error) {
	row := q.db.QueryRow(ctx, lockSquadForUpdate, arg.ID, arg.WorkspaceID)
	var i Squad
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Description,
		&i.LeaderID,
		&i.CreatorID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ArchivedAt,
		&i.ArchivedBy,
		&i.AvatarUrl,
		&i.Instructions,
		&i.InheritRuntimeSkills,
		&i.RuntimeSkillExceptions,
	)
	return i, err
}

const lockSquadNesting = `-- name: LockSquadNesting :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::uuid::text || ':squad_nesting', 0))
`

// Serializes every write that can close a squad loop or pair a sub-squad with
// its main squad's leader (ADR-0017). A row lock on one squad cannot: two adds
// on disjoint squads can close one loop together.
func (q *Queries) LockSquadNesting(ctx context.Context, workspaceID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, lockSquadNesting, workspaceID)
	return err
}

